import {ACTIVITIES,CIRCUIT,POCKET,SUDOKU,CROSSWORD,crosswordEntries,WORDS,localDay,readState,completedToday,streak,validateGrid,wordPath,makeWordGrid} from './core.js';

const $=s=>document.querySelector(s);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw new Error('Unavailable');}};}
let state=readState(storage), page=location.pathname.split('/').filter(Boolean)[0] || 'home', filter='all', generation=0, timers=[], activeId=null, circuitMode=false, startedAt=0;
if(!['home','mental-gym','mental-games','learning-lab'].includes(page))page='home';
