    const path=wordPath(start,end),text=path.map(i=>grid[i]).join(''),reverse=[...text].reverse().join(''),word=WORDS.find(w=>w===text||w===reverse);document.querySelectorAll('.word-cell.selected').forEach(c=>c.classList.remove('selected'));start=null;
    if(word&&!found.has(word)){found.add(word);path.forEach(i=>foundCells.add(i));foundCells.forEach(i=>$(`[data-word-cell="${i}"]`).classList.add('found'));$(`[data-word="${word}"]`).classList.add('found');$('.feedback').classList.remove('error');$('.feedback').textContent=`${word} found. ${found.size} of 5 words.`;if(found.size===5)finish([['5 / 5','Words found']],'You found every hidden word.');}else{$('.feedback').textContent=word?'You’ve already found that word.':'No word there yet. Try another pair of letters.';$('.feedback').classList.add('error');}
