const passages=[
  {title:'A clever way to remember',text:'Imagine you need to remember three errands: buy lemons, post a letter, and collect a book. Instead of repeating the list, picture a giant lemon blocking your front door, an envelope floating above your sofa, and a book balanced on your kitchen tap. This approach connects each item to a familiar location. To recall the list, mentally walk through those places in order. The striking images give you something concrete to retrieve. It takes a little preparation, but the route stays familiar even as the items change.',questions:[{q:'What anchors the items in this technique?',options:['Familiar locations','A strict time limit','Alphabetical order'],answer:0},{q:'Where was the envelope imagined?',options:['At the front door','Above the sofa','On the kitchen tap'],answer:1},{q:'How do you retrieve the list?',options:['Repeat each word ten times','Write the items backwards','Mentally walk through the locations'],answer:2}]},
  {title:'How a library finds its books',text:'A library’s catalogue connects a book to its place on a shelf. A catalogue entry may include the title, author, subject, and a call number. That call number acts like an address: it tells you which section to visit and where the book belongs within that section. Many libraries group nonfiction books by subject, while fiction may be arranged by the author’s surname. The catalogue can also tell you whether a copy is currently available. Finding a title in the catalogue is only the first step; reading its location gets you to the actual book.',questions:[{q:'What acts like the book’s shelf address?',options:['The publication year','The call number','The number of pages'],answer:1},{q:'How might fiction be arranged?',options:['By the author’s surname','By cover color','By page count'],answer:0},{q:'What else can a catalogue tell you?',options:['How quickly you will read','Whether you will enjoy the book','Whether a copy is available'],answer:2}]},
  {title:'A map with a useful distortion',text:'A transit map does not always represent a city’s geography precisely. Instead, it simplifies routes so passengers can understand connections. Lines may be straightened, stations spaced evenly, and bends reduced to a few consistent angles. The distance between two station symbols therefore may not match the walking distance above ground. What matters most is the order of stations and where lines intersect. For planning a transfer, that simplified view is useful. For deciding whether to walk between stops, a street map gives a better sense of actual distance.',questions:[{q:'What does a transit map prioritize?',options:['Building heights','Connections between stations','Exact walking distances'],answer:1},{q:'Why might station symbols be evenly spaced?',options:['To simplify the routes','Because all stops are equally far apart','To indicate ticket prices'],answer:0},{q:'Which map better helps you judge a walk?',options:['A transit diagram','A seating chart','A street map'],answer:2}]}
];
function playRead(){
  const entry=passages[[...localDay()].reduce((n,c)=>n+c.charCodeAt(0),0)%passages.length];let question=0,correct=0,locked=false;
  shell('Read & Recall',`<div class="reading"><p class="mono">TODAY’S SHORT READ · ${entry.text.split(' ').length} WORDS</p><h3>${entry.title}</h3><p>${entry.text}</p></div><p class="instructions">Read at your own pace. The passage disappears when you start the questions.</p><button class="button primary" id="ready-recall">I’m ready to recall ${icon('arrow')}</button>`,'LEARNING LAB · READ & RECALL');
  const ask=()=>{if(question===entry.questions.length){finish([[correct+'/3','Correct answers'],[Math.round(correct/3*100)+'%','Recall accuracy']],'You made time to read, then retrieve what you learned.');return;}locked=false;const q=entry.questions[question];
    shell('Read & Recall',`<div class="play-status"><span>QUESTION ${question+1} / 3</span><span>${correct} CORRECT</span></div><h3>${q.q}</h3><div class="answer-options">${q.options.map((o,i)=>`<button class="answer-option" data-choice="${i}">${o}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p><div class="play-actions"><button class="button primary" id="next-question" hidden>Next ${icon('arrow')}</button></div>`,'LEARNING LAB · READ & RECALL');
    document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(locked)return;locked=true;const right=Number(b.dataset.choice)===q.answer;if(right)correct++;document.querySelectorAll('[data-choice]').forEach(x=>{x.disabled=true;x.classList.toggle('correct',Number(x.dataset.choice)===q.answer);});if(!right)b.classList.add('incorrect');$('.feedback').textContent=right?'That’s right.':`The answer was: ${q.options[q.answer]}.`;$('.feedback').classList.toggle('error',!right);$('#next-question').hidden=false;});$('#next-question').onclick=()=>{question++;ask();};
  };$('#ready-recall').onclick=ask;
}
const defaultCards=[{q:'What is 15% of 200?',a:'30. Ten percent is 20; five percent is 10.'},{q:'Which direction is opposite to northeast?',a:'Southwest.'},{q:'What do the initials URL stand for?',a:'Uniform Resource Locator.'},{q:'How many sides does a hexagon have?',a:'Six.'},{q:'What is the next number: 3, 6, 12, 24…?',a:'48. Each number is twice the previous one.'}];
